window.RP_SESSION={"id":"S-f61771fdd7c2","messages":[{"id":"RP-II-0062183","time":"2026-03-13T22:50:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062184","time":"2026-03-13T22:50:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062185","time":"2026-03-13T22:50:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062186","time":"2026-03-13T22:51:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"다그닥 다그닥. 일반 군마의 두어배 정도 되는 덩치의 흑색 이각수. 골기아에서 서부로 향하는 한적한 길목.\n\n날도 구름이 듬성듬성 박힌 채로 높고, 맑다 못해 뜨거운 햇살이 하늘을 푸르게 비춘다.\n\n바이콘을 탄 기사, 아니 전사 한 명, 토르번이 유유자적하게 거닐고 있다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062187","time":"2026-03-13T22:51:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"기온은 제법 더워지기 시작했는지 늘 입던 모피 망토와 낡은 갑옷은 가방에 넣어 말 허리에 묶어둔 채였다.\n\n이것도 덥긴 하지만, 가죽갑옷과 편한 복장으로 갈아입은 폼이, 제법 기사보다는 모험가 같아보였다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062188","time":"2026-03-13T22:53:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"길은 슬슬 초록빛이 줄어들기 시작하고, 적갈색 황토가 섞여나오더니... 이윽고 붉은 빛의 사막이 저 멀리 보이기 시작했다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062189","time":"2026-03-13T22:53:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"사막에 도착하기에 앞서 마지막 정비라도 하라는 듯 커다란 마을이 들어서 있었다.\n\n사막의 아가리, '샤이-훌루다타'. 커다랗게 마을 입구에 써놓았다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062190","time":"2026-03-13T22:54:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"숙소를 빌리고, 마굿간에 바이콘을 데려다 놓자 해가 뚝떨어져 다 식어버린 겨울날 손처럼 아렸다. 북부만큼은 아니겠지만, 모피 망토 정도는 두르는 것이 좋아보였다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062191","time":"2026-03-13T22:55:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"놈이 얌전한 것은 다행인 일이었다. 다른 말이 있었더라면 시비를 걸든지 발정이나던지 했을 터인데, 무슨 일인지 말은 바이콘 혼자였다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062192","time":"2026-03-13T22:55:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...그러고 보니 네 이름을 안 정했구나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062193","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"천천히 말의 주둥이를 쓰다듬으며.\n\n\"션 형씨가 이름으로 부르는 건 들은 적이 없는데...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062194","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"생각해보니 그 양반은 나도 이름으로 부르지 않는군.\"\n\n\"뭐... 이름이란 중요한 걸세. 천천히 생각하지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062195","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"혼자 냅두는 것을 불만족스럽게 생각하는지 거칠게 콧소리를 내는 놈을 내버려둔 채, 숙소로 향했다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062196","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"꽁꽁이!","characters":[]},{"id":"RP-II-0062197","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"꽁꽁이 싫어!","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062198","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"까망이","characters":[]},{"id":"RP-II-0062199","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아오","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062200","time":"2026-03-13T22:56:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"꽝꽝이","characters":[]},{"id":"RP-II-0062201","time":"2026-03-13T22:57:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"혼자 떠나는 것은 익숙하지만 이리 제법 멀리 떠나온다는 것은 오래간만의 일이었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062202","time":"2026-03-13T22:57:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"unresolved","type":"dialogue","body":"말말이","characters":[]},{"id":"RP-II-0062203","time":"2026-03-13T22:57:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아무래도 가족이라는 장소가 제법 익숙해져버린 모양이지.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062204","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"뿔이 2개니깐 뿔뿔이","characters":[]},{"id":"RP-II-0062205","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"다 나가ㅋㅋㅋㅋㅋㅋㅋ","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062206","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"아니면 쌍뿔이","characters":[]},{"id":"RP-II-0062207","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"unresolved","type":"dialogue","body":"어림없지 ㅋㅋㅋ","characters":[]},{"id":"RP-II-0062208","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...혼자 있으니 환청마저 들리는구만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062209","time":"2026-03-13T22:58:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"혼자 있는 것이 이리도 익숙치 않았던가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062210","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그는 검을 만지작거리다가 이른 잠에 청했다. 내일은 의뢰인을 만나러 가야할 것이다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062211","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"아무래도 검으니깐 팹시","characters":[]},{"id":"RP-II-0062212","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"어떰","characters":[]},{"id":"RP-II-0062213","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062214","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062215","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062216","time":"2026-03-13T22:59:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"뿔 있고 사나우니 뿔쪽이.","characters":[]},{"id":"RP-II-0062217","time":"2026-03-13T23:00:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"이른 아침. 빵을 특이한 향신료에 찍어 먹는 조식이었다. 카레...인가? 비슷한 거 같기도하고.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062218","time":"2026-03-13T23:01:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"음.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062219","time":"2026-03-13T23:01:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"낙타를 빌리러 갔으나 어째서인지 모두가 손사레를 쳤다. 지금 떠나는 낙타는 없다라며.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062220","time":"2026-03-13T23:01:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"곤란하게 됐다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062221","time":"2026-03-13T23:02:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...하아...\"\n\n약속 시간이 되어가는데...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062222","time":"2026-03-13T23:02:00+09:00","room":"RP II","name":"에렌 아르슬란","profile":"에렌 아르슬란","identity":"unresolved","type":"dialogue","body":"더블콘","characters":[]},{"id":"RP-II-0062223","time":"2026-03-13T23:02:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"한숨을 푹푹 쉬며 돌아본 결과, 한마리도 없었다.\n\n그 대신, 뒤에 언제 탈출한지 모르는 바이콘 한마리가 나를 비웃고 있었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062224","time":"2026-03-13T23:02:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062225","time":"2026-03-13T23:03:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"바이콘이니깐 콘콘이\n메시지가 삭제되었습니다.","characters":[]},{"id":"RP-II-0062226","time":"2026-03-13T23:04:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...사막에서는 발이 푹푹 빠져서 마음껏 달릴 수 없다고. 짜증 엄청 낼 거면서.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062227","time":"2026-03-13T23:05:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"[히히히히-힝!]","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062228","time":"2026-03-13T23:06:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래그래... 이젠 어쩔 수 없다고 불평하지 말게나.\"\n\n이젠 능숙하게 바이콘의 위에 올라타 고삐를 몰았다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062229","time":"2026-03-13T23:07:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"의뢰인과의 약속 장소. 몸을 칭칭 가린 티플링 꼬마아이 하나와 전사로 보이는 덩치 큰 남성. 저 꼬마아이의 호위겠군.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062230","time":"2026-03-13T23:07:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"....?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062231","time":"2026-03-13T23:07:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"가까이 다가가자 일행이 보인다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062232","time":"2026-03-13T23:08:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"하나...둘....셋.........\n\n열............스물....?","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062233","time":"2026-03-13T23:08:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"꼬라지를 보아하니 티플링 집시들이다. 이건....","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062234","time":"2026-03-13T23:08:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"이봐. 자네들 어설픈 용맹에 호위 의뢰한 자들 아닌가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062235","time":"2026-03-13T23:09:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그러자 전사 녀석이 입을 열었다. 중년의 녀석은 덩치와는 달리 제법 지친 기색이었다.\n\n`그렇다. 호위를 의뢰했지.`","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062236","time":"2026-03-13T23:10:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...호위 대상은... 그 하나 인거지? 분명 단독이라 들었는데.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062237","time":"2026-03-13T23:11:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"`우리는 고행중이다. 비단요람을 로운델로 데려다다오.`","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062238","time":"2026-03-13T23:12:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"비단요람이란 게 이 꼬마아이를 가르키는 것이겠고.... 잡신이라도 모시는 건가? 로운델에서? 제정신인가?\n\n\"고행? 나머지 일행들은 뭔데?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062239","time":"2026-03-13T23:12:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"`게의치 마라. 알아서 따라붙을 터이니.`","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062240","time":"2026-03-13T23:12:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"하.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062241","time":"2026-03-13T23:13:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"바이콘에서 내려 이마를 짚고 한숨을 깊게 내쉬었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062242","time":"2026-03-13T23:14:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"장난하나? 지금 로운델이 어떤 분위기인지는 알고 이 티플링 덩어리들을 거기로 데려가라고? 그것도 잡신이나 모시는?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062243","time":"2026-03-13T23:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그러자 전사가 무례를 용서치 않겠다는 듯 검을 뽑으려 손을 움직이는 순간.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062244","time":"2026-03-13T23:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062245","time":"2026-03-13T23:15:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'토르번 팔켄하인'의 민첩 판정 :\n[9] + [1] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0062246","time":"2026-03-13T23:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번이 먼저 다가와 전사의 검을 붙잡아 누르고는 발을 걸어 넘어뜨렸다.\n\n\"이 개자식이 수작을 부려!\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062247","time":"2026-03-13T23:16:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"넘어진 전사에게 주먹을 내리꽂으려던 그때, 옆에 있던 '비단요람'이 토르번의 허리를 감싸안으며 막았다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062248","time":"2026-03-13T23:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아무 말도 하지 않았지만 9살... 10살 정도 되는 체구의 여자아이.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062249","time":"2026-03-13T23:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"정적에 모래 먼지만이 날리고. 토르번은 깊은 숨을 내리 쉬며 주먹을 거둬들였다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062250","time":"2026-03-13T23:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...이 의뢰는 없던 걸로 하지. 이딴 미친 짓거리를 할 생각은 추호도 없다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062251","time":"2026-03-13T23:18:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062252","time":"2026-03-13T23:18:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"'비단요람'은 아무 감정도 없이 나를 올려다보다가 몸을 놔줄 뿐이었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062253","time":"2026-03-13T23:18:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"머리를 벅벅 긁으며 주위를 둘러보았다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062254","time":"2026-03-13T23:19:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"집시에는... 다 늙어빠진 중년에서 노년. 어린아이들이 지친 듯 앉아서 눈치를 보고 있을 뿐이었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062255","time":"2026-03-13T23:19:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"미치겠네. 미치겠다. 미치겠어.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062256","time":"2026-03-13T23:19:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"나는 어린아이들이 싫다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062257","time":"2026-03-13T23:20:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"목표 이외에는 아무도 안 지킨다. 사막길에 픽픽 쓰러지든 말든.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062258","time":"2026-03-13T23:20:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"비단요람은 그제서야 화색이 돌며 나를 다시 끌어안았다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062259","time":"2026-03-13T23:20:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"정말 돌겠네.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062260","time":"2026-03-13T23:21:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...어른들은 마수에게 끌려가든, 강도에게 끌려가든, 비명을 지르며 반토막이 나든 행렬은 계속한다.\"\n\n\"그리고 로운델 가장 외곽까지만 호위하지. 그 이후로의 정치적인 일은 나는 모르는 일이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062261","time":"2026-03-13T23:23:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"`그거면 됐다네...`\n\n전사는 그제서야 부스스 모래를 털며 일어나 집시들을 채비시켰다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062262","time":"2026-03-13T23:23:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...다들 낙타가 있으면 낙타에 올라타고, 아니라면 걸어라.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062263","time":"2026-03-13T23:24:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...젠장....\"\n\n모두가 행렬을 시작할 때까지 착잡한 마음으로 청단풍 궐련 하나를 다 태우고는 모래에 짓밟아 껐다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062264","time":"2026-03-13T23:25:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"낙타들과 보행 행렬이 제법 눈에 띄었다.\n\n서걱.서걱. 토르번과 비단요람을 태운 바이콘이 행렬의 끝을 뒤따르며 고행이 시작되었다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062265","time":"2026-03-13T23:25:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 비단요람과 티플링 행렬","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-II-0062266","time":"2026-03-13T23:25:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
